CREATE TRIGGER IF NOT EXISTS retired_legacy_queue_update_v1 BEFORE UPDATE ON sync_queue WHEN EXISTS(SELECT 1 FROM pos_fiscal_checkout_retirements_v1 r JOIN json_tree(NEW.payload) j ON j.type='text' AND j.value IN (r.transaction_id,r.checkout_id,r.permit_id)) BEGIN SELECT RAISE(ABORT,'FISCAL_WORKFLOW_RETIREMENT_FENCED');END;
